import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CAKCj7G0.js";const d=JSON.parse('{"title":"React 基本介绍","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/11.react(谢杰)/codestation前台/*React* 基本介绍.md","filePath":"DuOneClass/11.react(谢杰)/codestation前台/*React* 基本介绍.md"}'),m={name:"DuOneClass/11.react(谢杰)/codestation前台/*React* 基本介绍.md"};function l(r,e,n,p,c,o){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="react-基本介绍" tabindex="-1"><em>React</em> 基本介绍 <a class="header-anchor" href="#react-基本介绍" aria-label="Permalink to &quot;*React* 基本介绍&quot;">​</a></h1><p>本章主要包含以下内容：</p><ul><li><em>React</em> 基本介绍</li><li><em>React</em> 特点</li><li>搭建开发环境</li></ul><h2 id="react-基本介绍-1" tabindex="-1"><em>React</em> 基本介绍 <a class="header-anchor" href="#react-基本介绍-1" aria-label="Permalink to &quot;*React* 基本介绍&quot;">​</a></h2><p><em>React</em> 起源于 <em>Facebook</em> 的内部项目，因为该公司对市场上所有 <em>JavaScript MVC</em> 框架都不满意，就决定自己写一套，用来架设 <em>Instagram</em> 的网站。</p><p><em>React</em> 的实质其实是一个用于构建用户界面的 <em>JavaScript</em> 库。<em>React</em> 主要用于构建 <em>UI</em>。<em>React</em> 于 <em>2013</em> 年 <em>5</em> 月开源，由于拥有较高的性能，代码逻辑简单，越来越多的人已开始关注和使用它。</p><blockquote><p><em>UI</em> = <em>fn(state)</em></p></blockquote><p>由于 <em>React</em> 的设计思想极其独特，属于革命性创新，性能出众，所以，越来越多的人开始关注和使用，认为它可能是将来 <em>Web</em> 开发的主流工具。</p><p>这个项目本身也越滚越大，从最早的 <em>UI</em> 引擎变成了一整套前后端通吃的 <em>Web App</em> 解决方案。</p><p><em>React</em> 官网：<em><a href="https://reactjs.org/" target="_blank" rel="noreferrer">https://reactjs.org/</a></em></p><p><em>React</em> 从诞生到现在，一直在给我们带来各种各样的惊喜。甚至从 <em>2015</em> 年开始，每年都会举行 <em>React Conf</em> 大会，介绍 <em>React</em> 本年度所更新的新特性有哪些。</p><p><img src="https://s2.loli.net/2025/01/28/MgrPwl289p4j7GZ.png" alt="image-20221027152326265"></p><blockquote><p><em>React Conf</em> 官网：<em><a href="https://conf.reactjs.org/" target="_blank" rel="noreferrer">https://conf.reactjs.org/</a></em></p><p><em>React Conf</em> 油管视频：<em><a href="https://www.youtube.com/channel/UC1hOCRBN2mnXgN5reSoO3pQ" target="_blank" rel="noreferrer">https://www.youtube.com/channel/UC1hOCRBN2mnXgN5reSoO3pQ</a></em></p></blockquote><p>下面介绍一下 <em>React</em> 几个重要版本的重大更新：</p><ul><li><em>React 16</em> :出现了 <em>Fiber</em>，整个更新变的可中断、可分片、具有优先级</li><li><em>React 16.8</em>：推出了 <em>Hooks</em>，标志着从类组件正式转为函数组件</li><li><em>React 17</em>：过渡版本，没有添加任何面向开发人员的新功能。而主要侧重于<strong>升级简化 <em>React</em> 本身</strong>。</li><li><em>React 18</em><ul><li><em>transition</em></li><li><em>Suspense</em></li><li>新的 <em>Hooks</em></li><li><em>Offscreen</em></li><li>......</li></ul></li></ul><h2 id="react-特点" tabindex="-1"><em>React</em> 特点 <a class="header-anchor" href="#react-特点" aria-label="Permalink to &quot;*React* 特点&quot;">​</a></h2><p>在 <em>React</em> 官网中，罗列了 <em>3</em> 个特点：</p><ul><li>声明式</li><li>组件化</li><li>一次学习，跨平台编写</li></ul><p>除此之外，<em>React</em> 还具有如下的特点：</p><ul><li>单向数据流</li><li>虚拟 <em>DOM</em></li><li><em>Diff</em> 算法</li></ul><h2 id="搭建开发环境" tabindex="-1">搭建开发环境 <a class="header-anchor" href="#搭建开发环境" aria-label="Permalink to &quot;搭建开发环境&quot;">​</a></h2><p>虽然官方提供了通过 <em>CDN</em> 引入 <em>React</em> 的方式：<em><a href="https://zh-hans.reactjs.org/docs/cdn-links.html" target="_blank" rel="noreferrer">https://zh-hans.reactjs.org/docs/cdn-links.html</a></em></p><p>但是实际开发中肯定是使用 <em>React</em> 的脚手架工具来搭建项目，<em>React</em> 官方提供了脚手架工具 <em>Create React App</em>：</p><p><em><a href="https://create-react-app.dev/" target="_blank" rel="noreferrer">https://create-react-app.dev/</a></em></p><p>快速开始：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npx create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">react</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app my</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd my</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,26)])])}const k=a(m,[["render",l]]);export{d as __pageData,k as default};
